}

.dialog-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: var(--spacing-xl);
    border-bottom: 1px solid var(--color-border);
}

.dialog-header h2 {
    font-size: 1.5rem;
    font-weight: 700;
    margin: 0;
}

.dialog-close {
    background: none;
